#!/bin/sh
# Builds a service's schema in a scratch database from its goose migrations (the Up part of each file, in order) without goose: schema.sh <database> <migrations dir>.
# For the backup tests and the point-in-time drill, which need the real tables to check real invariants. It also keeps goose's book (goose_db_version, one row per applied
# version), so that migrations-version.sh has something to read on a copy of the database. Environment: PG* of a role that may create objects.
set -eu
db="${1:?usage: schema.sh <database> <migrations dir>}"
dir="${2:?usage: schema.sh <database> <migrations dir>}"
psql -X -q -v ON_ERROR_STOP=1 -d "$db" -c "CREATE TABLE IF NOT EXISTS goose_db_version (id integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, version_id bigint NOT NULL, is_applied boolean NOT NULL, tstamp timestamp NOT NULL DEFAULT now()); INSERT INTO goose_db_version (version_id, is_applied) SELECT 0, true WHERE NOT EXISTS (SELECT 1 FROM goose_db_version)"
for f in $(ls "$dir"/*.sql | sort); do
  sed -n '/^-- +goose Up/,/^-- +goose Down/p' "$f" | psql -X -q -v ON_ERROR_STOP=1 -d "$db" -f -
  v="$(basename "$f" | sed 's/^\([0-9]*\)_.*/\1/' | sed 's/^0*//')"
  psql -X -q -v ON_ERROR_STOP=1 -d "$db" -c "INSERT INTO goose_db_version (version_id, is_applied) VALUES ($v, true)"
done
